<?php
$summary=paymentSummary($id,$order);$documents=all('SELECT * FROM documents WHERE order_id=? ORDER BY id DESC',[$id]);
?><?php if(!empty($order['source_quote_id'])):$accepted=row('SELECT number,accepted_at FROM documents WHERE id=?',[$order['source_quote_id']]);?><div class="notice info commerce-block">Commande issue du devis accepté <a href="<?=e(url('document',['id'=>$order['source_quote_id']]))?>"><?=e($accepted['number'])?></a>. Client et lignes commerciales verrouillés. Les documents reprennent les informations acceptées.</div><?php endif?><section class="panel padded commerce-block"><div class="panel-heading compact"><div><h2>Règlements & solde</h2><p>Les montants en attente ne réduisent pas le reste dû.</p></div></div><div class="finance-summary"><div><span>Net TTC après avoirs</span><strong><?=e(money(decimalString($summary['total'],2)))?></strong></div><div><span>Réglé confirmé</span><strong><?=e(money(decimalString($summary['paid'],2)))?></strong></div><div><span>En attente</span><strong><?=e(money(decimalString($summary['pending'],2)))?></strong></div><div><span>Avoirs déduits</span><strong><?=e(money(decimalString($summary['credited'],2)))?></strong></div><div><span>Solde en faveur du client</span><strong><?=e(money(decimalString($summary['available'],2)))?></strong></div><div><span>Reste à payer</span><strong><?=e(money(decimalString($summary['balance'],2)))?></strong></div></div>
<?php if($summary['pending']>$summary['balance']):?><p class="notice info">Les montants en attente dépassent le reste dû après avoirs. Vérifiez-les avant confirmation.</p><?php endif?>
<?php if($order['status']!=='Annulée'&&$summary['balance']-$summary['pending']>0):?><form method="post" class="payment-form" id="payment-form"><?=csrf()?><input type="hidden" name="action" value="payment_add"><input type="hidden" name="order_id" value="<?=$id?>"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><div class="form-grid three"><?php inputField('Montant · DH','amount','','number',true,'min="0.01" step="0.01" max="'.e(decimalString($summary['balance']-$summary['pending'],2)).'"');selectField('Méthode de paiement','method',PAYMENT_METHODS,$order['payment_method']);selectField('État','state',['Confirmé','En attente'],'Confirmé');?><label>Compte de trésorerie<select name="account_id"><option value="">Non affecté</option><?php foreach(all('SELECT id,name FROM finance_accounts ORDER BY name') as $a):?><option value="<?=(int)$a['id']?>"><?=e($a['name'])?></option><?php endforeach?></select></label><?php inputField('Date effective · si confirmé','financial_date',date('Y-m-d'),'date',false,'max="'.date('Y-m-d').'"');inputField('Référence / n° chèque','reference','','text',false,'maxlength="190"');?><div class="field-action"><button class="btn primary">Ajouter le règlement</button></div></div><p class="small muted">Un compte peut être affecté depuis Caisse & banque. Un chèque est créé en attente. Le bouton « Confirmer » sert à constater son encaissement.</p></form><?php endif?>
<?php $payments=all('SELECT * FROM order_payments WHERE order_id=? ORDER BY id DESC',[$id]);if($payments):?><div class="table-scroll"><table><thead><tr><th>AJOUTÉ LE</th><th>MÉTHODE</th><th>RÉFÉRENCE</th><th>ÉTAT</th><th class="numeric">MONTANT</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=e(localDate($p['created_at']))?></td><td><?=e($p['method'])?></td><td><?=e($p['reference'])?:'—'?></td><td><span class="tag <?=$p['state']==='Confirmé'?'green':($p['state']==='Annulé'?'gray':'yellow')?>"><?=e($p['state'])?></span><?php if($p['confirmed_at']):?><small class="subline">Confirmé le <?=e(localDate($p['confirmed_at']))?></small><?php endif?></td><td class="numeric"><?=e(money($p['amount']))?></td><td><div class="row-actions"><?php foreach(($p['state']==='En attente'?['Confirmé'=>'Confirmer','Annulé'=>'Annuler']:($p['state']==='Confirmé'?['Annulé'=>'Annuler']:[])) as $state=>$label):?><form method="post" data-confirm="<?=e($state==='Annulé'?'Annuler ce règlement en conservant sa trace ?':'Confirmer que ce montant est réellement encaissé ?')?>"><?=csrf()?><input type="hidden" name="action" value="payment_state"><input type="hidden" name="payment_id" value="<?=(int)$p['id']?>"><input type="hidden" name="state" value="<?=e($state)?>"><button class="text-button"><?=e($label)?></button></form><?php endforeach?></div></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
<section class="panel padded commerce-block"><h2>Devis, facture & avoirs</h2><p class="muted small">Les coordonnées du client et de votre entreprise sont reprises automatiquement et conservées avec le document. Une facture par commande ; plusieurs versions de devis possibles.</p><div class="export-actions"><?php foreach(['quote'=>'Créer un devis','invoice'=>'Émettre / ouvrir la facture'] as $kind=>$label):?><form method="post" <?=$kind==='invoice'?'data-confirm="Émettre la facture et verrouiller les montants de cette commande ?"':''?>><?=csrf()?><input type="hidden" name="action" value="document_create"><input type="hidden" name="order_id" value="<?=$id?>"><input type="hidden" name="kind" value="<?=e($kind)?>"><button class="btn <?=$kind==='invoice'?'primary':'secondary'?>"><?=e($label)?></button></form><?php endforeach?></div><?php foreach($documents as $doc):?><div class="document-row"><a class="record-title" href="<?=e(url('document',['id'=>$doc['id']]))?>"><?=e($doc['number'])?> · <?=e(documentType($doc))?></a><span class="small muted"><?=e(localDate($doc['created_at']))?></span><a class="btn secondary" href="<?=e(url('document',['id'=>$doc['id'],'download'=>'pdf']))?>">↓ PDF</a></div><?php endforeach?></section>
